---Refresh
---@param data table
---@param index number
---@param isSlot boolean 是否是呱呱乐
function ActivityFashionPreheatingHistoryNode:Refresh(data , index, isSlot)
    isSlot = checkBool(isSlot)
    self.index = index
    local timeStr = os.date("%Y.%m.%d %H:%M" , data.time)
    local playerName = data.playerName
    if isSlot then
        CfUtils.FillText(self.TxtTitle.gameObject , localize("_time_ _playerName_ 瓜分获得" ,{_time_ = timeStr , _playerName_ = playerName}))
        ---@type GoodsVo
        local goodsVo = GoodsUtils.GetGoodsVoById(data.rewardId)
        CfUtils.FillText(self.TxtName.gameObject ,  localize("_name_ x_num_", {
            _name_ = goodsVo.name,
            _num_ = checkNumber(data.rewardNum),
        }))
    else
        local cardSkinVo = CfUtils.GetCfVo(AutoIds.IdSetting113, "CardSkinVo", data.cardSkinId)
        local name = cardSkinVo.name
        CfUtils.FillText(self.TxtTitle.gameObject , localize("_time_ _playerName_ 瓜分获得" ,{_time_ = timeStr , _playerName_ = playerName}))
        CfUtils.FillText(self.TxtName.gameObject , name)
    end
    self:FillSelf()
end

function ActivityFashionPreheatingHistoryNode:FillSelf()
    if self._co then
        CfUtils.PlayDelayShowAnimate(self.controller.gameObject, self.index, 0, 0, "Default")
       return
    end
    self._co = CfUtils.PlayDelayShowAnimate(self.controller.gameObject, self.index, 0.05, 0, "Go")
end

function ActivityFashionPreheatingHistoryNode:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

return ActivityFashionPreheatingHistoryNode